<?php
/** MCP and the panel use the same WordPress queue, versions and upstream receipts. */
class AiWebsite {
    private $store;
    public function __construct($store){$this->store=$store;}
    private function service(){require_once dirname(__DIR__).'/WordPressWorkspace.php';return new WordPressWorkspace();}
    private function kind($input){$kind=$input['kind']??'posts';if(!in_array($kind,['products','posts','pages','taxonomies','sales'],true))throw new RuntimeException('نوع دادهٔ سایت معتبر نیست.');return $kind;}
    public function read($project,$input){$kind=$this->kind($input);$offset=$input['offset']??0;$limit=$input['limit']??30;if(!is_int($offset)||$offset<0||!is_int($limit)||$limit<1||$limit>100)throw new RuntimeException('بازهٔ دریافت سایت معتبر نیست.');$svc=$this->service();$rows=$svc->rows($project,$kind,$offset,$limit);$state=$svc->state($project['id']);$total=count($state['index'][$kind]??[]);return ['project'=>$project['id'],'kind'=>$kind,'rows'=>$rows,'total'=>$total,'next_offset'=>$offset+count($rows)<$total?$offset+count($rows):null,'last_received'=>$state['last_received'][$kind]??null,'last_complete'=>$state['last_complete'][$kind]??null,'note'=>'این داده از آخرین دریافت واقعی است؛ نبود دریافت به معنی خالی بودن سایت نیست.'];}
    public function preview($project,$grant,$input){AiAccess::scope($grant,'website.write');AiAccess::write();AiAccess::need('wp_crm','use');$kind=$this->kind($input);if($kind==='sales')throw new RuntimeException('فروش فقط خواندنی است.');if($kind==='products')AiAccess::need('products','use');$id=$input['id']??'';if(!is_string($id)||$id==='')throw new RuntimeException('شناسهٔ دقیق سایت لازم است.');$row=$this->service()->record($project,$kind,$id);$changes=$input['changes']??null;$allowed=['title','description','seo_title','seo_description','seo_keyword'];if(!is_array($changes)||!$changes||array_diff(array_keys($changes),$allowed))throw new RuntimeException('فیلدهای تغییر سایت معتبر نیستند.');foreach($changes as $v)if(!is_string($v)||strlen($v)>100000)throw new RuntimeException('مقدار تغییر معتبر نیست.');
        $before=['title'=>$row['title']??$row['name']??'','description'=>$row['content_html']??$row['description']??'','seo_title'=>$row['seo_title']??'','seo_description'=>$row['seo_description']??'','seo_keyword'=>$row['focus_keyword']??''];$after=array_replace($before,$changes);if(trim($after['title'])==='')throw new RuntimeException('عنوان نمی‌تواند خالی باشد.');$after['expected_version']=$row['version']??null;$after['expected_modified_at']=$row['modified_at']??null;$draft=bin2hex(random_bytes(16));$entry=['project'=>$project['id'],'owner'=>$grant['owner'],'kind'=>$kind,'id'=>$id,'input'=>$after,'config'=>hash('sha256',json_encode($project['settings']['wordpress']??[])),'expires'=>time()+900];
        $this->store->transaction(static function(&$s)use($draft,$entry){foreach($s['website_drafts']??[] as $key=>$r)if($r['expires']<time())unset($s['website_drafts'][$key]);$s['website_drafts'][$draft]=$entry;});return ['draft'=>$draft,'before'=>$before,'after'=>array_intersect_key($after,$before),'expires_at'=>$entry['expires'],'published'=>false,'instruction'=>'تفاوت‌ها را به کاربر نشان دهید؛ فقط پس از تأیید او website_confirm را فراخوانی کنید.'];
    }
    public function confirm($project,$grant,$input){AiAccess::scope($grant,'website.write');AiAccess::write();if(($input['confirmed']??false)!==true)throw new RuntimeException('تأیید صریح تغییرات لازم است.');$id=$input['draft']??'';$draft=$this->store->read()['website_drafts'][$id]??null;if(!$draft||$draft['project']!==$project['id']||$draft['owner']!==$grant['owner']||$draft['expires']<time()||$draft['config']!==hash('sha256',json_encode($project['settings']['wordpress']??[])))throw new RuntimeException('پیش‌نمایش معتبر این پروژه یافت نشد؛ دوباره پیش‌نمایش بگیرید.');$job=$this->service()->queueContent($project,$draft['kind'],$draft['id'],$draft['input']);$this->store->transaction(static function(&$s)use($grant,$job){AiStore::audit($s,$grant,'website_queued',['job'=>$job]);});return ['job'=>$job,'state'=>'queued','published'=>false,'note'=>'فقط در صف قرار گرفت؛ موفقیت انتشار پس از دریافت رسید واقعی سایت مشخص می‌شود.'];}
    public function job($project,$input){AiAccess::need('wp_crm');$id=$input['id']??'';$job=$this->service()->state($project['id'])['jobs'][$id]??null;if(!$job)throw new RuntimeException('کار سایت در این پروژه یافت نشد.');if($job['kind']==='product')AiAccess::need('products');return array_intersect_key($job,array_flip(['id','kind','remote_id','state','at','completed_at','error','result']));}
}
